          padding: const EdgeInsets.only(top: 6),
          child: Text(
            '${message.role} · ${strings.unitChars(message.chars)}',
            style: dim,
          ),
        ),
        Text(
          message.preview,
          style: Theme.of(context).textTheme.bodySmall?.copyWith(
            color: Theme.of(context).colorScheme.onSurfaceVariant,
          ),
